function Auth({signup=false}:{signup?:boolean}){const[type,setType]=useState(new URLSearchParams(location.search).get('type')||new URLSearchParams(location.search).get('role')||'');const[email,setEmail]=useState('');const[password,setPassword]=useState('');const[name,setName]=useState('');const[busy,setBusy]=useState(false);const[message,setMessage]=useState('');const nav=useNavigate();async function submit(e:React.FormEvent){e.preventDefault();if(signup&&!['business','investor'].includes(type)){setMessage('Choose whether you are joining as a Business or an Investor.');return;}if(!supabase){setMessage('Authentication is not configured yet. Add the Supabase environment variables to enable accounts.');return;}setBusy(true);setMessage('');try{if(signup){const{data,error}=await supabase.auth.signUp({email,password,options:{data:{full_name:name,account_type:type},emailRedirectTo:location.origin+import.meta.env.BASE_URL+'dashboard?tab=overview'}});if(error)throw error;if(data.session){nav('/dashboard?tab=overview',{replace:true});}else{setMessage('Account created. Check your email to verify it; the confirmation link will take you straight to your Overview.');}}else{const{error}=await supabase.auth.signInWithPassword({email,password});if(error)throw error;nav('/dashboard?tab=overview',{replace:true});}}catch(err){setMessage(err instanceof Error?err.message:'Something went wrong.');}finally{setBusy(false)}}async function google(){if(!supabase){setMessage('Authentication is not configured yet.');return;}const role=type;if(!['business','investor'].includes(role)){setMessage('Choose Business or Investor before continuing with Google.');return;}const{error}=await supabase.auth.signInWithOAuth({provider:'google',options:{redirectTo:location.origin+import.meta.env.BASE_URL+'dashboard?tab=overview'+(role?'&oauth_role='+encodeURIComponent(role):'')}});if(error)setMessage(error.message)}async function resetPassword(){if(!supabase||!email){setMessage('Enter your email address first.');return;}setBusy(true);const{error}=await supabase.auth.resetPasswordForEmail(email,{redirectTo:location.origin+import.meta.env.BASE_URL+'reset-password'});setBusy(false);setMessage(error?'Unable to send reset email: '+error.message:'Password reset link sent. Check your inbox.');}return <div className="auth-page"><div className="auth-aside"><Logo light/><div><div className="eyebrow"><span className="eyebrow-line"/> THE VENTORA NETWORK</div><h1>Build the<br/><em>next connection.</em></h1><p>A more considered space for ambitious businesses and thoughtful investors.</p><span className="auth-aside-foot">WHERE AMBITION MEETS OPPORTUNITY.</span></div></div><div className="auth-main"><Link to="/" className="back-home">← Back to home</Link><div className="auth-box"><div className="section-kicker">{signup?'CREATE YOUR ACCOUNT':'WELCOME BACK'}</div><h2>{signup?'Your next chapter starts here.':'Good to see you again.'}</h2><p>{signup?'Choose how you want to use Ventora Connect.':'New to Ventora? Choose your account type before continuing with Google. Existing accounts keep their saved account type.'}</p>{<div className="role-select" role="group" aria-label="Choose your account type"><button type="button" aria-pressed={type==='business'} className={type==='business'?'selected':''} onClick={()=>{setType('business');setMessage('')}}><Building2/>Business</button><button type="button" aria-pressed={type==='investor'} className={type==='investor'?'selected':''} onClick={()=>{setType('investor');setMessage('')}}><ChartNoAxesCombined/>Investor</button></div>}<form onSubmit={submit}>{signup&&<label>Full name<input required value={name} onChange={e=>setName(e.target.value)} placeholder="Your name"/></label>}<label>Email address<input required type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@company.com"/></label><label>Password<input required minLength={8} type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="At least 8 characters"/></label><button className="btn btn-dark auth-submit" disabled={busy}>{busy?'Please wait…':signup?'Create account':'Log in'} <ArrowUpRight size={17}/></button></form>{<div className="auth-extras">{signup&&<button type="button" className="btn btn-outline-dark google-btn" onClick={google}>Continue with Google <ArrowUpRight size={16}/></button>}{!signup&&<button type="button" className="text-link" onClick={resetPassword}>Forgot password?</button>}{!signup&&<button type="button" className="btn btn-outline-dark google-btn" onClick={google}>Continue with Google <ArrowUpRight size={16}/></button>}</div>}{message&&<div className="form-message" role="status">{message}</div>}<div className="auth-switch">{signup?'Already have an account?':'New to Ventora?'} <Link to={signup?'/login':'/signup'}>{signup?'Log in':'Create an account'}</Link></div><div className="auth-legal">By continuing, you agree to our <Link to="/terms">Terms</Link> and <Link to="/privacy">Privacy Policy</Link>.</div></div></div></div>}
function PasswordReset(){const[password,setPassword]=useState('');const[message,setMessage]=useState('');const[busy,setBusy]=useState(false);async function submit(e:React.FormEvent){e.preventDefault();if(!supabase)return;setBusy(true);const{error}=await supabase.auth.updateUser({password});setBusy(false);setMessage(error?error.message:'Password updated. You can now log in with your new password.');}return <div className="auth-page"><div className="auth-aside"><Logo light/><div><div className="eyebrow">ACCOUNT SECURITY</div><h1>Make your<br/><em>next move secure.</em></h1></div></div><div className="auth-main"><Link to="/" className="back-home">← Back to home</Link><div className="auth-box"><div className="section-kicker">RESET PASSWORD</div><h2>Choose a new password.</h2><form onSubmit={submit}><label>New password<input required minLength={8} type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="At least 8 characters"/></label><button className="btn btn-dark auth-submit" disabled={busy}>{busy?'Updating…':'Update password'} <ArrowUpRight size={17}/></button></form>{message&&<div className="form-message" role="status">{message}</div>}<div className="auth-switch"><Link to="/login">Return to login</Link></div></div></div></div>}
function Dashboard(){return <Workspace/>}
function Directory({investors=false}:{investors?:boolean}){
const[query,setQuery]=useState(''),[industry,setIndustry]=useState(''),[stage,setStage]=useState(''),[ticket,setTicket]=useState('');const[items,setItems]=useState<any[]>([]);const[loading,setLoading]=useState(true);const[error,setError]=useState('');const[viewer,setViewer]=useState<any>(null);const[busy,setBusy]=useState('');const[message,setMessage]=useState('');const[savedIds,setSavedIds]=useState<string[]>([]);const nav=useNavigate();
useEffect(()=>{let active=true;let authSub:any;const client=supabase;if(!client){setLoading(false);return()=>{active=false}}async function load(){const{data:sessionData}=await client.auth.getSession();const current=sessionData.session?.user||null;if(active)setViewer(current);let result:any;if(investors){result=await client.from('discoverable_profiles').select('id,full_name,bio,avatar_url,country,city,website,account_type,investment_min,investment_max,preferred_industries,preferred_stages').eq('account_type','investor').limit(60);}else{result=await supabase.from('discoverable_businesses').select('id,company_name,industry,description,country,city,business_stage,funding_requirement,min_investment,max_investment,owner_id,logo_url,cover_image_url').limit(60);}if(!active)return;if(result.error)setError(result.error.message);else setItems(result.data||[]);if(current){const table=investors?'saved_investors':'saved_businesses',key=investors?'investor_id':'business_id';const saved=await client.from(table).select(key).eq('user_id',current.id);if(active)setSavedIds((saved.data||[]).map((x:any)=>x[key]));}setLoading(false);}load();const auth=client.auth.onAuthStateChange((_event,session)=>{if(active){setViewer(session?.user||null);if(!session?.user)setSavedIds([]);}});authSub=auth.data.subscription;return()=>{active=false;authSub?.unsubscribe()}},[investors]);
async function ensureViewer(){if(!supabase)return null;const{data}=await supabase.auth.getSession();const current=data.session?.user||null;setViewer(current);return current}
async function messageMember(target:string){if(!supabase){nav('/login');return;}const current=viewer||await ensureViewer();if(!current){nav('/login?next='+encodeURIComponent(location.pathname));return;}if(current.id===target){setMessage('This is your own profile.');return;}setBusy('message-'+target);setMessage('');const{data,error}=await supabase.rpc('start_conversation',{target_user:target});setBusy('');if(error)setMessage(error.message);else nav('/messages?conversation='+data);}
async function save(target:string){if(!supabase){nav('/login');return;}const current=viewer||await ensureViewer();if(!current){nav('/login?next='+encodeURIComponent(location.pathname));return;}const table=investors?'saved_investors':'saved_businesses',key=investors?'investor_id':'business_id';setBusy('save-'+target);setMessage('');if(savedIds.includes(target)){const{error}=await supabase.from(table).delete().eq('user_id',current.id).eq(key,target);setBusy('');if(error)setMessage(error.message);else{setSavedIds(old=>old.filter(x=>x!==target));setMessage('Removed from your shortlist.');}}else{const{error}=await supabase.from(table).upsert({user_id:current.id,[key]:target},{onConflict:'user_id,'+key});setBusy('');if(error)setMessage(error.message);else{setSavedIds(old=>[...old,target]);setMessage('Saved to your shortlist.');}}}
const industries=Array.from(new Set(items.flatMap(item=>investors?(item.preferred_industries||[]):[item.industry]).filter(Boolean))).sort();const stages=Array.from(new Set(items.flatMap(item=>investors?(item.preferred_stages||[]):[item.business_stage]).filter(Boolean))).sort();
const filtered=items.filter(item=>{const haystack=investors?[item.full_name,item.bio,item.city,item.country,...(item.preferred_industries||[]),...(item.preferred_stages||[])].join(' '):[item.company_name,item.description,item.industry,item.city,item.country,item.business_stage].join(' ');const low=investors?Number(item.investment_min||0):Number(item.min_investment||item.funding_requirement||0);const high=investors?Number(item.investment_max||item.investment_min||0):Number(item.max_investment||item.funding_requirement||0);const amount=low||high;const ticketOk=!ticket||(ticket==='under-10'&&amount>0&&amount<10000)||(ticket==='10-50'&&amount>=10000&&amount<=50000)||(ticket==='50-plus'&&amount>50000);return haystack.toLowerCase().includes(query.toLowerCase())&&(!industry||((investors?(item.preferred_industries||[]).join(' '):item.industry||'').toLowerCase().includes(industry.toLowerCase())))&&(!stage||((investors?(item.preferred_stages||[]).join(' '):item.business_stage||'').toLowerCase().includes(stage.toLowerCase())))&&ticketOk});
const money=(value:any)=>value==null?'Not disclosed':'₹'+Number(value).toLocaleString('en-IN',{maximumFractionDigits:0});
return <><Header/><section className={"directory-hero "+(investors?"directory-investor-hero":"directory-business-hero")}><div className="section-kicker">VENTORA DISCOVERY / {investors?'INVESTORS':'BUSINESSES'}</div><h1>{investors?'Meet the people':'Discover businesses'}<br/><em>moving ideas forward.</em></h1><p>{investors?'Explore investor profiles and understand their stated interests.':'Explore published company profiles, funding needs and founders.'}</p>{!investors&&<div className="directory-hero-actions"><div><span className="directory-live-dot"/> OPEN FOR BUSINESS DISCOVERY</div><Link className="directory-create-link" to={viewer?'/dashboard?tab=business':'/signup?type=business'}>{viewer?'Manage your listings':'List your business'} <ArrowUpRight size={17}/></Link></div>}<div className="directory-search"><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={investors?'Search investors, industries or locations':'Search companies, industries or locations'} aria-label="Search directory"/><select value={industry} onChange={e=>setIndustry(e.target.value)} aria-label="Filter by industry"><option value="">All industries</option>{industries.map(v=><option key={v} value={v}>{v}</option>)}</select><select value={stage} onChange={e=>setStage(e.target.value)} aria-label="Filter by stage"><option value="">All stages</option>{stages.map(v=><option key={v} value={v}>{v}</option>)}</select><select value={ticket} onChange={e=>setTicket(e.target.value)} aria-label="Filter by ticket size"><option value="">Any ticket size</option><option value="under-10">Under ₹10,000</option><option value="10-50">₹10,000–₹50,000</option><option value="50-plus">Above ₹50,000</option></select></div></section><section className="directory-results"><div className="directory-intro-row"><div><span className="section-kicker">THE VENTORA NETWORK</span><h2>{investors?"People behind the capital.":"Ideas worth getting to know."}</h2></div><p>{investors?"Explore investor profiles and their stated interests.":"A curated space for ambitious companies, clear profiles and meaningful introductions."}</p></div><div className="directory-result-head"><span>{loading?'Loading profiles…':error?'Directory unavailable':filtered.length+' profiles found'}</span><span>MEMBER-PUBLISHED PROFILES</span></div>{message&&<div className="workspace-notice">{message}</div>}{error&&<div className="directory-note">{error}. Please check that the Ventora database migrations have been applied.</div>}{loading?<div className="directory-empty">Loading the network…</div>:!filtered.length?<div className="directory-empty"><div className="directory-empty-icon"><Building2 size={28}/></div><span className="section-kicker">A NEW NETWORK STARTS SOMEWHERE</span><h3>{investors?'No investor profiles match these filters.':'No businesses match these filters yet.'}</h3><p>{investors?'Try another industry, stage or ticket size.':'Try adjusting your filters, or publish your company profile when it is ready.'}</p><Link className="btn btn-dark" to={viewer?'/dashboard?tab=business':'/signup?type=business'}>{viewer?'Create your first listing':'Create a business listing'} <ArrowUpRight/></Link></div>:<div className="directory-grid">{filtered.map(item=>{const target=investors?item.id:item.owner_id;const isSaved=savedIds.includes(item.id);const title=investors?item.full_name:item.company_name;const min=investors?item.investment_min:item.min_investment;const max=investors?item.investment_max:item.max_investment;const targetAmount=investors?null:item.funding_requirement;return <article className="directory-card" key={item.id}><div className="directory-card-cover">{!investors&&item.cover_image_url?<img src={item.cover_image_url} alt={title+" cover"}/>:<div className="directory-cover-art"><span>VENTORA / DISCOVERY</span>{investors?<ChartNoAxesCombined size={34}/>:<Building2 size={34}/>}</div>}<span className="directory-card-category">{investors?'INVESTOR':(item.industry||'BUSINESS').toUpperCase()}</span><span className="directory-card-trust"><ShieldCheck size={12}/> MEMBER PROFILE</span></div><div className="directory-card-body"><div className="directory-card-heading">{!investors&&item.logo_url?<img src={item.logo_url} alt={title+" logo"}/>:item.avatar_url?<img src={item.avatar_url} alt={title+" avatar"}/>:<span className="directory-avatar">{(title||'V').slice(0,1).toUpperCase()}</span>}<div><h3>{title}</h3><small>{investors?'Investor profile':item.business_stage||'Business profile'}</small></div></div><p className="directory-card-hook">{item.bio||item.description||'A Ventora member building meaningful opportunities.'}</p><div className="directory-card-pills">{!investors&&item.industry&&<span>{item.industry}</span>}<span>{investors?'Investor':item.business_stage||'Stage not specified'}</span></div><div className="directory-card-stats">{investors?<><div><small>MIN TICKET</small><b>{money(min)}</b></div><div><small>MAX TICKET</small><b>{money(max)}</b></div><div><small>FOCUS</small><b>{(item.preferred_industries||[]).slice(0,1).join('')||'Flexible'}</b></div></>:<><div><small>RAISE TARGET</small><b>{money(targetAmount)}</b></div><div><small>MIN TICKET</small><b>{money(min)}</b></div><div><small>LOCATION</small><b>{[item.city,item.country].filter(Boolean).join(', ')||'Not shared'}</b></div></>}</div>{!investors&&<div className="directory-funding-track"><div><span>FUNDING TARGET</span><small>{targetAmount==null?'Not disclosed':'Target disclosed'}</small></div><div className="directory-funding-line"><i/></div></div>}<div className="directory-meta"><span>{[item.city,item.country].filter(Boolean).join(', ')||'Location not specified'}</span>{investors&&<span>{(item.preferred_stages||[]).slice(0,2).join(' · ')||'Stages flexible'}</span>}</div><div className="directory-card-actions"><Link className="text-link" to={investors?'/member/'+item.id:'/business/'+item.id}>View profile <ArrowUpRight size={16}/></Link><button className={'directory-save-toggle'+(isSaved?' is-saved':'')} type="button" onClick={()=>save(item.id)} disabled={busy==='save-'+item.id} aria-pressed={isSaved} aria-label={isSaved?'Remove from shortlist':'Add to shortlist'}><Bookmark size={15} fill={isSaved?'currentColor':'none'}/><span>{busy==='save-'+item.id?'Saving…':isSaved?'Shortlisted':'Shortlist'}</span></button><button className="directory-message-button" type="button" onClick={()=>messageMember(target)} disabled={busy==='message-'+target}>{busy==='message-'+target?'Opening…':'Message'}</button></div></div></article>})}</div>}</section><Footer/></>}
function PublicProfile({investor=false}:{investor?:boolean}){const{id}=useParams();const[item,setItem]=useState<any>(null);const[gallery,setGallery]=useState<any[]>([]);const[loading,setLoading]=useState(true);const[message,setMessage]=useState('');const nav=useNavigate();useEffect(()=>{let active=true;async function load(){if(!supabase||!id){setLoading(false);return;}const result=investor?await supabase.from('discoverable_profiles').select('*').eq('id',id).eq('account_type','investor').maybeSingle():await supabase.from('discoverable_businesses').select('*').eq('id',id).maybeSingle();if(result.data){const{data:viewer}=await supabase.auth.getUser();if(viewer.user&&viewer.user.id!==(investor?result.data.id:result.data.owner_id)){await supabase.from('profile_views').insert({viewer_id:viewer.user.id,...(investor?{viewed_profile_id:result.data.id}:{business_id:result.data.id})})}}if(active){setItem(result.data);if(!investor&&result.data?.id){const g=await supabase.from('business_gallery_images').select('id,image_url,sort_order').eq('business_id',result.data.id).order('sort_order');setGallery(g.data||[]);}if(result.error)setMessage(result.error.message);setLoading(false)}}load();return()=>{active=false}},[id,investor]);async function messageMember(){if(!supabase){nav('/login');return;}const{data}=await supabase.auth.getUser();if(!data.user){nav('/login');return;}const target=investor?item.id:item.owner_id;if(data.user.id===target){setMessage('This is your own profile.');return;}const{data:conversation,error}=await supabase.rpc('start_conversation',{target_user:target});if(error)setMessage(error.message);else nav('/messages?conversation='+conversation)}async function blockMember(){if(!supabase){nav('/login');return;}const{data}=await supabase.auth.getUser();if(!data.user){nav('/login');return;}const target=investor?item.id:item.owner_id;if(data.user.id===target)return;if(!window.confirm('Block this member? You will no longer see each other in discovery or message each other.'))return;const{error}=await supabase.from('user_blocks').insert({blocker_id:data.user.id,blocked_id:target});setMessage(error?error.message:'Member blocked.');if(!error)nav(investor?'/investors':'/businesses')}async function reportMember(){if(!supabase){nav('/login');return;}const{data}=await supabase.auth.getUser();if(!data.user){nav('/login');return;}const target=investor?item.id:item.owner_id;if(data.user.id===target)return;const reason=window.prompt('Briefly describe the issue (e.g. misleading profile, impersonation, harassment):');if(!reason?.trim())return;const{error}=await supabase.from('reports').insert({reporter_id:data.user.id,reported_user_id:target,reason:reason.trim(),details:'Submitted from member profile.'});setMessage(error?error.message:'Report submitted for review.')}async function expressInterest(){if(!supabase){nav('/login');return;}const{data}=await supabase.auth.getUser();if(!data.user){nav('/login');return;}const{data:me}=await supabase.from('profiles').select('account_type').eq('id',data.user.id).maybeSingle();if(me?.account_type!=='investor'){setMessage('Only investor accounts can express investment interest.');return;}const{error}=await supabase.from('investment_interests').insert({investor_id:data.user.id,business_id:item.id});setMessage(error?error.message:'Your expression of interest has been sent.')}if(loading)return <div className="workspace-loading">Loading profile…</div>;if(!item)return <Info title="Profile unavailable." copy="This profile may be private, unpublished or no longer available."/>;return <><Header/><section className="public-profile-hero">{!investor&&item.cover_image_url&&<img src={item.cover_image_url} alt={item.company_name+" cover"} style={{width:"100%",maxHeight:280,objectFit:"cover",borderRadius:18,marginBottom:28}}/>}<div className="section-kicker">VENTORA CONNECT / {investor?'INVESTOR':'BUSINESS'} PROFILE</div><div className="public-profile-title">{!investor&&item.logo_url?<img src={item.logo_url} alt={item.company_name+" logo"} className="public-profile-avatar" style={{objectFit:"cover"}}/>:<div className="public-profile-avatar">{(investor?item.full_name:item.company_name||'V').slice(0,1).toUpperCase()}</div>}<div><h1>{investor?item.full_name:item.company_name}</h1><p>{investor?'Investor profile':item.industry||'Business'} · {[item.city,item.country].filter(Boolean).join(', ')||'Location not specified'}</p></div></div><div className="public-profile-actions"><button className="btn btn-lime" onClick={messageMember}>Message directly <ArrowUpRight size={17}/></button>{!investor&&<button className="btn btn-lime" onClick={expressInterest}>Express investment interest <ArrowUpRight size={17}/></button>}<Link className="btn btn-outline" to={investor?'/investors':'/businesses'}>Back to discovery</Link><button className="btn btn-outline" onClick={blockMember}>Block member</button><button className="btn btn-outline" onClick={reportMember}>Report</button></div>{message&&<div className="workspace-notice">{message}</div>}</section><section className="public-profile-body"><article className="public-profile-about"><span className="section-kicker">OVERVIEW</span><h2>{investor?'Investment perspective':'About the business'}</h2><p>{investor?item.bio:item.description||'This business has not added a description yet.'}</p>{investor&&<><h3>Investment interests</h3><div className="directory-meta">{(item.preferred_industries||[]).map((x:string)=><span key={x}>{x}</span>)}{(item.preferred_stages||[]).map((x:string)=><span key={x}>{x}</span>)}</div>{item.investment_min!=null&&<p>Indicative investment range: {Number(item.investment_min).toLocaleString()} – {Number(item.investment_max||item.investment_min).toLocaleString()}</p>}</>}</article>{!investor&&gallery.length>0&&<section className="public-business-gallery"><span className="section-kicker">INSIDE THE COMPANY</span><h2>Company <em>gallery.</em></h2><div>{gallery.map((photo:any)=><img key={photo.id} src={photo.image_url} alt="Company gallery photo"/>)}</div></section>}{!investor&&<aside className="public-profile-facts"><div><span>BUSINESS STAGE</span><b>{item.business_stage||'Not specified'}</b></div><div><span>FUNDING REQUIREMENT</span><b>{item.funding_requirement==null?'Not disclosed':'₹'+Number(item.funding_requirement).toLocaleString('en-IN')}</b></div><div><span>MINIMUM INVESTMENT</span><b>{item.min_investment==null?'Not disclosed':'₹'+Number(item.min_investment).toLocaleString('en-IN')}</b></div><div><span>EQUITY OFFERED</span><b>{item.equity_offered==null?'Not disclosed':item.equity_offered+'%'}</b></div>{item.website&&<a href={item.website} target="_blank" rel="noreferrer">Visit website <ArrowUpRight size={15}/></a>}</aside>}</section><Footer/></>}
function PaymentComingSoon(){const params=new URLSearchParams(window.location.search);const planId=params.get('plan')||'';const catalog:Record<string,{name:string;price:string;audience:string}>={business_growth:{name:'Growth',price:'₹699',audience:'Business membership'},business_scale:{name:'Scale',price:'₹1,699',audience:'Business membership'},investor_access:{name:'All Access',price:'₹1',audience:'Investor membership'}};const plan=catalog[planId];return <><Header/><main className="simple-page payment-coming-soon"><span className="section-kicker">VENTORA CONNECT / MEMBERSHIP</span><div className="payment-coming-icon"><Sparkles size={28}/></div><h1>Payments are <em>coming soon.</em></h1><p>{plan?<>You're interested in the <strong>{plan.name}</strong> {plan.audience.toLowerCase()} at <strong>{plan.price}/month</strong>. Payment methods are not available yet. Secure checkout will be available here soon.</>:<>Secure subscription checkout is being prepared. Payment methods will be available here soon.</>}</p><div className="payment-coming-note"><strong>No payment has been taken.</strong><span>Your plan will not activate until secure payment processing launches.</span></div><div className="workspace-actions"><Link className="btn btn-dark" to="/dashboard">Back to dashboard <ArrowUpRight size={17}/></Link><Link className="btn btn-outline-dark" to="/dashboard">Back to membership plans</Link></div></main><Footer/></>}
function FAQ(){const questions=[['What is Ventora Connect?','Ventora Connect is a business and investor discovery and networking platform. Members can publish profiles, explore the network, message members directly and express non-binding interest.'],['Does Ventora handle investments or payments?','No. The platform does not collect investment funds, execute transfers, provide escrow, issue securities or complete equity transactions.'],['Does a verified badge guarantee an investment is safe?','No. Verification only reflects a review step. It does not guarantee identity beyond the scope of the review, financial accuracy, business quality or investment outcomes.'],['Who can create an account?','Members choose either a business or investor account during registration. Account type is protected and cannot be changed through profile editing.'],['How do I contact support?','Use the support centre to submit a request connected to your member account.'],['How are private documents handled?','Verification documents are stored in a private Supabase Storage bucket. Access is restricted to the submitting member and authorised reviewers.']];return <><Header/><section className="directory-hero"><div className="section-kicker">VENTORA CONNECT / HELP CENTRE</div><h1>Good questions.<br/><em>Clear answers.</em></h1><p>Learn how the Ventora network works and what it does—and does not—do.</p></section><section className="faq-list">{questions.map(([q,a],i)=><article key={q}><span>0{i+1}</span><div><h2>{q}</h2><p>{a}</p></div></article>)}</section><section className="faq-cta"><h2>Still need a hand?</h2><Link className="btn btn-dark" to="/support">Contact support <ArrowUpRight/></Link></section><Footer/></>}
function Info({title,copy}:{title:string;copy:string}){return <><Header/><section className="directory-hero"><div className="section-kicker">VENTORA CONNECT</div><h1>{title}</h1><p>{copy}</p><Link className="btn btn-dark" to="/signup">Join the network <ArrowUpRight/></Link></section><Footer/></>}
function PageLoading(){return <div className="page-loading"><BrandLoader/><strong>Preparing your next opportunity</strong><span>VENTORA CONNECT</span></div>}
function IntroSplash({onDone}:{onDone:()=>void}){const letters='VENTORA'.split('');useEffect(()=>{const timer=window.setTimeout(onDone,2750);return()=>window.clearTimeout(timer)},[onDone]);return <motion.div className="ventora-intro" initial={{opacity:1}} exit={{opacity:0,transition:{duration:.45}}}><div className="intro-light intro-light-one"/><div className="intro-light intro-light-two"/><motion.div className="intro-brand-lockup" initial={{opacity:0,scale:.92,y:16}} animate={{opacity:1,scale:1,y:0}} transition={{duration:.7,ease:[.16,1,.3,1]}}><motion.img className="intro-logo-mark" src="/ventora-icon.svg" alt="Ventora Connect logo" initial={{opacity:0,rotate:-35,scale:.65}} animate={{opacity:1,rotate:0,scale:1}} transition={{delay:.12,duration:.8,ease:[.16,1,.3,1]}}/><div className="intro-word">{letters.map((letter,i)=><motion.span key={i} initial={{opacity:0,y:26,filter:'blur(7px)'}} animate={{opacity:1,y:0,filter:'blur(0px)'}} transition={{delay:.35+i*.075,duration:.48,ease:[.16,1,.3,1]}}>{letter}</motion.span>)}</div><motion.div className="intro-connect" initial={{opacity:0,letterSpacing:'.7em'}} animate={{opacity:1,letterSpacing:'.38em'}} transition={{delay:1.02,duration:.7}}>CONNECT</motion.div><motion.div className="intro-tagline" initial={{opacity:0,y:8}} animate={{opacity:1,y:0}} transition={{delay:1.42,duration:.45}}>WHERE AMBITION MEETS OPPORTUNITY</motion.div></motion.div><motion.div className="intro-progress" initial={{scaleX:0}} animate={{scaleX:1}} transition={{duration:2.25,ease:'linear'}}/></motion.div>}
export default function App(){return <Suspense fallback={<PageLoading/>}><Routes><Route path="/" element={<GustPlatform/>}/><Route path="/signup" element={<Auth signup/>}/><Route path="/login" element={<Auth/>}/><Route path="/dashboard" element={<Dashboard/>}/><Route path="/payment-coming-soon" element={<PaymentComingSoon/>}/><Route path="/messages" element={<Messages/>}/><Route path="/interests" element={<Interests/>}/><Route path="/matches" element={<Matches/>}/><Route path="/saved" element={<Saved/>}/><Route path="/announcements" element={<Announcements/>}/><Route path="/admin" element={<Admin/>}/><Route path="/support" element={<Support/>}/><Route path="/reset-password" element={<PasswordReset/>}/><Route path="/businesses" element={<Directory/>}/><Route path="/business/:id" element={<PublicProfile/>}/><Route path="/member/:id" element={<PublicProfile investor/>}/><Route path="/investors" element={<Directory investors/>}/><Route path="/about" element={<Info title="A network for the next generation of ambition." copy="Ventora Connect brings businesses and investors together through thoughtful discovery, trusted profiles and meaningful conversations."/>}/><Route path="/faq" element={<FAQ/>}/><Route path="/help" element={<FAQ/>}/><Route path="/contact" element={<Support/>}/><Route path="/how-it-works" element={<Info title="From discovery to conversation." copy="Create a profile, explore members whose stated preferences align with yours, message them directly, and continue the conversation privately."/>}/><Route path="/business-solutions" element={<Info title="A more considered way to meet investors." copy="Build a company profile, explain your funding requirements, share a private pitch deck, discover investors and manage expressions of interest. Publishing a profile does not guarantee funding."/>}/><Route path="/investor-solutions" element={<Info title="Discover businesses with context." copy="Define your investment interests, explore published company profiles, request conversations and track non-binding expressions of interest. Ventora does not provide investment advice or execute investments."/>}/><Route path="/success-stories" element={<Info title="Real outcomes, when they are ready to be shared." copy="There are no verified Ventora success stories to publish yet. We will only feature stories with the participants’ permission and clear supporting context."/>}/><Route path="/privacy" element={<Legal doc="privacy"/>}/><Route path="/terms" element={<Legal doc="terms"/>}/><Route path="/risk" element={<Legal doc="risk"/>}/><Route path="/legal/:doc" element={<Legal/>}/><Route path="*" element={<Info title="This page is on its way." copy="The page you're looking for isn't available yet."/>}/></Routes></Suspense>}